    .z80
    .module x1Scc
    .area _CODE
    .allow_undocumented

.include /setting.inc/
.include /nekoSys.inc/
.include /x1Scc.inc/

.ifdef ENABLE_SCC

PORT_FM_REGISTER_NO .equ 0x0700

; @param[in]    D   レジスタ番号
; @param[in]    E   値
FM_WRITE:
    PUSH BC
        LD BC,#PORT_FM_REGISTER_NO
        OUT (C),D
        INC C
        OUT (C),E
    POP BC
    RET


; @param[in]    A   チャンネル番号(0～7)
FM_CHANNEL_ON:
    LD BC,#PORT_FM_REGISTER_NO
    LD L,#0x08
    OUT (C),L
    INC C
    OR #0x78
    OUT (C),A
    RET

; @param[in]    A   チャンネル番号(0～7)
FM_CHANNEL_OFF:
    LD BC,#PORT_FM_REGISTER_NO
    LD L,#0x08
    OUT (C),L
    INC C
    AND #0x07
    OUT (C),A
    RET

; @param[in]    A   チャンネル番号(0～7)
; @param[in]    L   設定するTLの値
FM_SET_CHANNEL_TL:
    LD BC,#PORT_FM_REGISTER_NO
    ADD #0x60
    OUT (C),A
    INC C
    OUT (C),L

    DEC C
    ADD #0x08
    OUT (C),A
    INC C
    OUT (C),L

    DEC C
    ADD #0x08
    OUT (C),A
    INC C
    OUT (C),L

    DEC C
    ADD #0x08
    OUT (C),A
    INC C
    OUT (C),L
    RET


; @param[in]    A   チャンネル番号(0～7)
; @param[in]    HL  SCCのレジスタの値
FM_SET_FREQ:
    ADD HL,HL
    LD DE,#KEY_TABLE
    ADD HL,DE
    LD E,(HL) ; KEY CODE
    INC HL
    LD H,(HL) ; KEY FRECTION
; @param[in]    A   チャンネル番号(0～7)
; @param[in]    E   KEY CODE
; @param[in]    H   KEY FRECTION
    ; KEY CODE
    LD BC,#PORT_FM_REGISTER_NO
    ADD #0x28
    OUT (C),A
    INC C
    OUT (C),E
    ; KEY FRECTION
    DEC C
    ADD #0x08
    OUT (C),A
    INC C
    OUT (C),H
    RET

    .globl initSCC

;;
; SCC初期化
;;
initSCC:
    ; SCCレジスタ書き込みのフックを設定
    LD HL,#writeSCC
    LD (0x0321+1),HL
    LD A,#0xC3
    LD (0x0321),A
    RET

;;
; SSCレジスタへの書き込み
;
; @param[in]    A   書き込む値
; @param[in]    DE  書き込むレジスタ
;;
writeSCC:
    PUSH BC
    PUSH DE
    PUSH HL
        LD D,A
        LD A,E
        CP #0x80
        JP Z,SCC_FREQUENCY_CHANNEL1_LOW
        CP #0x81
        JP Z,SCC_FREQUENCY_CHANNEL1_HIGH
        CP #0x82
        JP Z,SCC_FREQUENCY_CHANNEL2_LOW
        CP #0x83
        JP Z,SCC_FREQUENCY_CHANNEL2_HIGH
        CP #0x84
        JP Z,SCC_FREQUENCY_CHANNEL3_LOW
        CP #0x85
        JP Z,SCC_FREQUENCY_CHANNEL3_HIGH
        CP #0x86
        JP Z,SCC_FREQUENCY_CHANNEL4_LOW
        CP #0x87
        JP Z,SCC_FREQUENCY_CHANNEL4_HIGH
        CP #0x86
        JP Z,SCC_FREQUENCY_CHANNEL5_LOW
        CP #0x87
        JP Z,SCC_FREQUENCY_CHANNEL5_HIGH
        CP #0x8F
        JP Z,SCC_SWITCH_CHANNEL ; on/off switch channel 1 to 5
        CP #0x8A
        JP Z,SCC_VOLUME_CHANNEL1
        CP #0x8B
        JP Z,SCC_VOLUME_CHANNEL2
        CP #0x8C
        JP Z,SCC_VOLUME_CHANNEL3
        CP #0x8D
        JP Z,SCC_VOLUME_CHANNEL4
        CP #0x8E
        JP Z,SCC_VOLUME_CHANNEL5
writeSCC_EXIT:
    POP HL
    POP DE
    POP BC
    RET

SCC_FREQUENCY_CHANNEL1_LOW:
    LD A,D
    LD (SCC_FREQ_1),A
    JR SCC_FREQUENCY_CHANNEL1
SCC_FREQUENCY_CHANNEL1_HIGH:
    LD A,D
    LD (SCC_FREQ_1+1),A
SCC_FREQUENCY_CHANNEL1:
    LD A,#0x00
    LD HL,(SCC_FREQ_1)
    CALL FM_SET_FREQ
    JP writeSCC_EXIT

SCC_FREQUENCY_CHANNEL2_LOW:
    LD A,D
    LD (SCC_FREQ_2),A
    JR SCC_FREQUENCY_CHANNEL2
SCC_FREQUENCY_CHANNEL2_HIGH:
    LD A,D
    LD (SCC_FREQ_2+1),A
SCC_FREQUENCY_CHANNEL2:
    LD A,#0x01
    LD HL,(SCC_FREQ_2)
    CALL FM_SET_FREQ
    JP writeSCC_EXIT

SCC_FREQUENCY_CHANNEL3_LOW:
    LD A,D
    LD (SCC_FREQ_3),A
    JR SCC_FREQUENCY_CHANNEL3
SCC_FREQUENCY_CHANNEL3_HIGH:
    LD A,D
    LD (SCC_FREQ_3+1),A
SCC_FREQUENCY_CHANNEL3:
    LD A,#0x02
    LD HL,(SCC_FREQ_3)
    CALL FM_SET_FREQ
    JP writeSCC_EXIT

SCC_FREQUENCY_CHANNEL4_LOW:
    LD A,D
    LD (SCC_FREQ_4),A
    JR SCC_FREQUENCY_CHANNEL4
SCC_FREQUENCY_CHANNEL4_HIGH:
    LD A,D
    LD (SCC_FREQ_4+1),A
SCC_FREQUENCY_CHANNEL4:
    LD A,#0x03
    LD HL,(SCC_FREQ_4)
    CALL FM_SET_FREQ
    JP writeSCC_EXIT

SCC_FREQUENCY_CHANNEL5_LOW:
    LD A,D
    LD (SCC_FREQ_5),A
    JR SCC_FREQUENCY_CHANNEL5
SCC_FREQUENCY_CHANNEL5_HIGH:
    LD A,D
    LD (SCC_FREQ_5+1),A
SCC_FREQUENCY_CHANNEL5:
    LD A,#0x04
    LD HL,(SCC_FREQ_5)
    CALL FM_SET_FREQ
    JP writeSCC_EXIT

SCC_SWITCH_CHANNEL:
    BIT 0,D
    LD A,#0x00
    CALL NZ,FM_CHANNEL_ON
    CALL Z,FM_CHANNEL_OFF
    BIT 1,D
    LD A,#0x01
    CALL NZ,FM_CHANNEL_ON
    CALL Z,FM_CHANNEL_OFF
    BIT 2,D
    LD A,#0x02
    CALL NZ,FM_CHANNEL_ON
    CALL Z,FM_CHANNEL_OFF
    BIT 3,D
    LD A,#0x03
    CALL NZ,FM_CHANNEL_ON
    CALL Z,FM_CHANNEL_OFF
    BIT 4,D
    LD A,#0x04
    CALL NZ,FM_CHANNEL_ON
    CALL Z,FM_CHANNEL_OFF
    JP writeSCC_EXIT

; The volume is stored in the same way as in the PSG, though it does not support envelopes.
; Bits 0 to 3 contain a volume of 0 to 15, and bits 7 to 4 are ignored.
; A volume of 0 is silent, and a volume of 15 is maximum volume.
SCC_VOLUME_CHANNEL1:
    LD A,D
    AND #0x0F
    LD HL,#VOLUME_TABLE
    ADD L
    LD L,A
    LD L,(HL)
    LD A,#0x00
    CALL FM_SET_CHANNEL_TL
    JP writeSCC_EXIT
SCC_VOLUME_CHANNEL2:
    LD A,D
    AND #0x0F
    LD HL,#VOLUME_TABLE
    ADD L
    LD L,A
    LD L,(HL)
    LD A,#0x01
    CALL FM_SET_CHANNEL_TL
    JP writeSCC_EXIT
SCC_VOLUME_CHANNEL3:
    LD A,D
    AND #0x0F
    LD HL,#VOLUME_TABLE
    ADD L
    LD L,A
    LD L,(HL)
    LD A,#0x02
    CALL FM_SET_CHANNEL_TL
    JP writeSCC_EXIT
SCC_VOLUME_CHANNEL4:
    LD A,D
    AND #0x0F
    LD HL,#VOLUME_TABLE
    ADD L
    LD L,A
    LD L,(HL)
    LD A,#0x03
    CALL FM_SET_CHANNEL_TL
    JP writeSCC_EXIT
SCC_VOLUME_CHANNEL5:
    LD A,D
    AND #0x0F
    LD HL,#VOLUME_TABLE
    ADD L
    LD L,A
    LD L,(HL)
    LD A,#0x04
    CALL FM_SET_CHANNEL_TL
    JP writeSCC_EXIT

;;
; SCCの周波数のレジスタ 1チャンネル
;;
SCC_FREQ_1:
    .DW 0x00

;;
; SCCの周波数のレジスタ 2チャンネル
;;
SCC_FREQ_2:
    .DW 0x00

;;
; SCCの周波数のレジスタ 3チャンネル
;;
SCC_FREQ_3:
    .DW 0x00

;;
; SCCの周波数のレジスタ 4チャンネル
;;
SCC_FREQ_4:
    .DW 0x00

;;
; SCCの周波数のレジスタ 5チャンネル
;;
SCC_FREQ_5:
    .DW 0x00

;;
; 音量の変換テーブル
; @todo 調整
;;
VOLUME_TABLE:
FM_V_OFF .equ 2
FM_V_S   .equ 2
    .DB 0x7F,               14*FM_V_S+FM_V_OFF, 14*FM_V_S+FM_V_OFF, 14*FM_V_S+FM_V_OFF
    .DB 14*FM_V_S+FM_V_OFF, 14*FM_V_S+FM_V_OFF, 14*FM_V_S+FM_V_OFF, 13*FM_V_S+FM_V_OFF
    .DB 12*FM_V_S+FM_V_OFF, 11*FM_V_S+FM_V_OFF,  9*FM_V_S+FM_V_OFF,  7*FM_V_S+FM_V_OFF
    .DB  5*FM_V_S+FM_V_OFF,  3*FM_V_S+FM_V_OFF,  0*FM_V_S+FM_V_OFF,  0*FM_V_S+FM_V_OFF

;;
; SCCの周波数からFM音源のキーコードとキーフリクションへの変換テーブル
